begin;
create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
select no_plan();

select extensions.dblink_connect('s3_setup','host=host.docker.internal port=54322 dbname=postgres user=postgres password=postgres');
select extensions.dblink_exec('s3_setup',$setup$
  delete from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001';
  delete from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' or status_request_id in(select id from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001');
  delete from public.alerts where vehicle_id='c4000000-0000-0000-0000-000000000001'; delete from public.tracking_history where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.vehicle_locations where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.documents where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001';
  delete from public.shipments where id='c5000000-0000-0000-0000-000000000001'; delete from public.vehicles where id='c4000000-0000-0000-0000-000000000001'; delete from public.drivers where id='c2000000-0000-0000-0000-000000000001'; delete from public.clients where id='c3000000-0000-0000-0000-000000000001'; delete from public.profiles where id::text like 'c1000000-%'; delete from auth.users where id::text like 'c1000000-%';
  drop function if exists public.s3_reset(public.shipment_status,boolean,boolean); drop function if exists public.s3_capture_cancel(); drop function if exists public.s3_capture_edit(); drop function if exists public.s3_capture_request(); drop function if exists public.s3_capture_approve(); drop function if exists public.s3_capture_reject(); drop function if exists public.s3_capture_account(); drop function if exists public.s3_capture_driver_lifecycle(); drop function if exists public.s3_capture_vehicle_lifecycle(); drop function if exists public.s3_capture_tracking_document_alert();
  insert into auth.users(id) values('c1000000-0000-0000-0000-000000000001'),('c1000000-0000-0000-0000-000000000002'),('c1000000-0000-0000-0000-000000000003');
  insert into public.profiles(id,full_name,username,role,is_active) values('c1000000-0000-0000-0000-000000000001','Race Admin','s3-race-admin','admin',true),('c1000000-0000-0000-0000-000000000002','Race Dispatcher','s3-race-dispatcher','dispatcher',true),('c1000000-0000-0000-0000-000000000003','Race Driver','s3-race-driver','driver',true);
  insert into public.drivers(id,profile_id,status) values('c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000003','assigned'); insert into public.clients(id,company_name) values('c3000000-0000-0000-0000-000000000001','Race Client'); insert into public.vehicles(id,registration,make,model,vehicle_type,status) values('c4000000-0000-0000-0000-000000000001','S3-RACE','Test','Race','Truck','in_use');
  insert into public.shipments(id,tracking_number,client_id,pickup_address,delivery_address,pickup_at,expected_delivery_at,cargo_type,driver_id,vehicle_id,price,status) values('c5000000-0000-0000-0000-000000000001','SHP-S3-RACE','c3000000-0000-0000-0000-000000000001','A','B',now(),now(),'Cargo','c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',1,'assigned');
  create function public.s3_reset(target_status public.shipment_status,add_request boolean,add_tracking boolean) returns void language plpgsql security definer set search_path='' as $fn$ begin
    delete from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' or status_request_id in(select id from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001'); delete from public.alerts where vehicle_id='c4000000-0000-0000-0000-000000000001' or shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.tracking_history where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.vehicle_locations where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.documents where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001'; update public.profiles set is_active=true where id='c1000000-0000-0000-0000-000000000003'; update public.drivers set status='assigned' where id='c2000000-0000-0000-0000-000000000001'; update public.vehicles set status='in_use' where id='c4000000-0000-0000-0000-000000000001'; update public.shipments set status=target_status,delayed=(target_status='in_transit'),pickup_address='A' where id='c5000000-0000-0000-0000-000000000001';
    if target_status='in_transit' then insert into public.alerts(id,alert_type,severity,message,alert_state,shipment_id,vehicle_id,driver_id,document_id,resolved_at,resolved_by_profile_id) values('c8000000-0000-0000-0000-000000000002','shipment_delayed','warning','Shipment SHP-S3-RACE has been marked as delayed.','active','c5000000-0000-0000-0000-000000000001',null,null,null,null,null); end if;
    if add_request then insert into public.shipment_status_requests(id,shipment_id,driver_id,current_status,requested_status) values('c6000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000001','c2000000-0000-0000-0000-000000000001',target_status,case target_status when 'assigned' then 'loading'::public.shipment_status when 'loading' then 'in_transit'::public.shipment_status else 'delivered'::public.shipment_status end); end if;
    if add_tracking then insert into public.vehicle_locations(vehicle_id,shipment_id,latitude,longitude,speed,heading,route_progress) values('c4000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000001',45,19,1,1,50); insert into public.alerts(id,alert_type,severity,message,vehicle_id) values('c8000000-0000-0000-0000-000000000001','stale_vehicle_location','critical','Stale','c4000000-0000-0000-0000-000000000001'); insert into public.documents(id,shipment_id,uploader_profile_id,document_type,file_path,file_name) values('c7000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000003','proof_of_delivery','s3/race/pod.pdf','pod.pdf'); end if;
  end $fn$;
  create function public.s3_capture_cancel() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.cancel_shipment('c5000000-0000-0000-0000-000000000001');return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_edit() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.update_shipment_details('c5000000-0000-0000-0000-000000000001',(select updated_at from public.shipments where id='c5000000-0000-0000-0000-000000000001'),'Edited','B',now(),now(),'Cargo',1);return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_request() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.create_shipment_status_request('loading');return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_approve() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.approve_shipment_status_request('c6000000-0000-0000-0000-000000000001');return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_reject() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.reject_shipment_status_request('c6000000-0000-0000-0000-000000000001',null);return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_account() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.set_managed_account_active_state('s3-race-driver',false);return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_driver_lifecycle() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.change_driver_operational_status('c2000000-0000-0000-0000-000000000001','mark_off_duty');return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_vehicle_lifecycle() returns text language plpgsql security definer set search_path='' as $fn$ begin perform public.change_vehicle_operational_status('c4000000-0000-0000-0000-000000000001','mark_maintenance');return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
  create function public.s3_capture_tracking_document_alert() returns text language plpgsql security definer set search_path='' as $fn$ begin update public.documents set lifecycle_status='archived' where id='c7000000-0000-0000-0000-000000000001';update public.vehicle_locations set speed=2 where vehicle_id='c4000000-0000-0000-0000-000000000001';update public.alerts set message='Checked' where id='c8000000-0000-0000-0000-000000000001';return 'success';exception when others then return sqlstate||':'||sqlerrm;end $fn$;
$setup$);
select extensions.dblink_connect('s3_a','host=host.docker.internal port=54322 dbname=postgres user=postgres password=postgres'); select extensions.dblink_connect('s3_b','host=host.docker.internal port=54322 dbname=postgres user=postgres password=postgres');

-- Cancel versus cancel.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$); select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001'''); select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000002''');
select ok(extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()')=1,'First cancel starts');select pg_sleep(.1);select ok(extensions.dblink_send_query('s3_b','select public.s3_capture_cancel()')=1,'Second cancel starts');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(result like '40001:%','Cancel replay loses safely') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select is((select value from extensions.dblink('s3_setup',$$select count(*)::int from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' and action_type='shipment_cancelled'$$) as t(value integer)),1,'Cancel/cancel commits exactly one cancellation activity');
select is((select value from extensions.dblink('s3_setup',$$select count(*)::int from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001' and notification_type='shipment_cancelled'$$) as t(value integer)),1,'Cancel/cancel commits exactly one cancellation notification');

-- Edit versus edit.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_send_query('s3_a','select public.s3_capture_edit()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_edit()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(result in ('success','40001:shipment_edit_stale'),'Competing edit resolves safely') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select is((select value from extensions.dblink('s3_setup',$$select count(*)::int from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' and action_type='shipment_updated'$$) as t(value integer)),1,'Edit/edit commits exactly one edit activity');

-- Cancellation serializes with request creation.
-- Cancellation versus edit leaves no post-cancellation edit.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_edit()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select isnt(result,'success','Edit loses after committed cancellation') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select ok((select value from extensions.dblink('s3_setup',$$select (status='cancelled' and pickup_address='A' and (select count(*) from public.activity_logs where shipment_id=shipments.id and action_type='shipment_updated')=0) from public.shipments where id='c5000000-0000-0000-0000-000000000001'$$) as t(value boolean)),'Cancel/edit leaves cancelled state with no losing edit effect');

-- Edit and compatible S2 approval serialize without partial state.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',true,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000002''');select extensions.dblink_send_query('s3_a','select public.s3_capture_edit()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_approve()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select is(result,'success','Compatible approval succeeds after edit') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','commit');
select ok((select value from extensions.dblink('s3_setup',$$select status='loading' and pickup_address='Edited' from public.shipments where id='c5000000-0000-0000-0000-000000000001'$$) as t(value boolean)),'Edit/approval preserves both compatible outcomes');

select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000003''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_request()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select isnt(result,'success','Request cannot survive committed cancellation') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select is((select value from extensions.dblink('s3_setup',$$select count(*)::int from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001' and request_state='pending'$$) as t(value integer)),0,'Cancel/request creation leaves no pending request');

-- Cancellation serializes with approve and reject.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',true,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000002''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_approve()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select isnt(result,'success','Approval loses after cancellation rejects request') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select ok((select value from extensions.dblink('s3_setup',$$select request_state='rejected' and rejection_reason='Shipment cancelled' and (select count(*) from public.activity_logs where status_request_id=shipment_status_requests.id and action_type='status_request_rejected')=1 from public.shipment_status_requests where id='c6000000-0000-0000-0000-000000000001'$$) as t(value boolean)),'Cancel/approval leaves one exact cancellation-triggered rejection');
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',true,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000002''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_reject()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select isnt(result,'success','Manual rejection loses after cancellation rejection') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select is((select value from extensions.dblink('s3_setup',$$select count(*)::int from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001' and notification_type='status_rejected'$$) as t(value integer)),0,'Cancel/rejection suppresses status-rejected notification');

-- Lifecycle competitors cannot produce partial release or deadlocks.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role service_role;set local lock_timeout=''5s'';set local statement_timeout=''10s''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_account()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(position('deadlock detected' in result)=0,'Account lifecycle race has no deadlock') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_driver_lifecycle()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(position('deadlock detected' in result)=0,'Driver lifecycle race has no deadlock') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('assigned',false,false); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_vehicle_lifecycle()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(position('deadlock detected' in result)=0,'Vehicle lifecycle race has no deadlock') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','rollback');

-- In-transit cancellation versus POD, location, and stale-alert mutation.
select extensions.dblink_exec('s3_setup',$reset$do $do$ begin perform public.s3_reset('in_transit',true,true); end $do$;$reset$);select extensions.dblink_exec('s3_a','begin;set local role authenticated;set local lock_timeout=''5s'';set local statement_timeout=''10s'';set local "request.jwt.claim.sub"=''c1000000-0000-0000-0000-000000000001''');select extensions.dblink_exec('s3_b','begin;set local lock_timeout=''5s'';set local statement_timeout=''10s''');select extensions.dblink_send_query('s3_a','select public.s3_capture_cancel()');select pg_sleep(.1);select extensions.dblink_send_query('s3_b','select public.s3_capture_tracking_document_alert()');select * from extensions.dblink_get_result('s3_a',false) as r(result text);select * from extensions.dblink_get_result('s3_a',false) as r(result text);select extensions.dblink_exec('s3_a','commit');select ok(position('deadlock detected' in result)=0,'Tracking, alert, and POD competitor has no deadlock') from extensions.dblink_get_result('s3_b',false) as r(result text);select * from extensions.dblink_get_result('s3_b',false) as r(result text);select extensions.dblink_exec('s3_b','commit');

select is((select count(*) from extensions.dblink('s3_setup',$$select 1 from public.shipments s join public.drivers d on d.id=s.driver_id join public.vehicles v on v.id=s.vehicle_id where s.id='c5000000-0000-0000-0000-000000000001' and s.status='cancelled' and d.status='available' and v.status='available'$$) as t(value integer)),1::bigint,'Final cancellation has no partial resource release');
select ok((select value from extensions.dblink('s3_setup',$$select not exists(select 1 from public.vehicle_locations where shipment_id='c5000000-0000-0000-0000-000000000001') and (select count(*) from public.tracking_history where shipment_id='c5000000-0000-0000-0000-000000000001')=1 and (select alert_state='resolved' from public.alerts where id='c8000000-0000-0000-0000-000000000001')$$) as t(value boolean)),'Tracking/POD/alert race leaves exact tracking and alert state');
select ok((select value from extensions.dblink('s3_setup',$$select (select count(*) from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' and action_type='shipment_cancelled')=1 and (select count(*) from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' and action_type='tracking_stopped')=1 and (select count(*) from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001' and notification_type='shipment_cancelled')=1$$) as t(value boolean)),'In-transit race commits exact activity and notification counts');
select ok(position('deadlock detected' in extensions.dblink_error_message('s3_a'))=0 and position('deadlock detected' in extensions.dblink_error_message('s3_b'))=0,'No race reports a deadlock');

select extensions.dblink_disconnect('s3_a');select extensions.dblink_disconnect('s3_b');
select extensions.dblink_exec('s3_setup',$cleanup$ delete from public.notifications where shipment_id='c5000000-0000-0000-0000-000000000001'; delete from public.activity_logs where shipment_id='c5000000-0000-0000-0000-000000000001' or status_request_id in(select id from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001'); delete from public.alerts where vehicle_id='c4000000-0000-0000-0000-000000000001' or shipment_id='c5000000-0000-0000-0000-000000000001';delete from public.tracking_history where shipment_id='c5000000-0000-0000-0000-000000000001';delete from public.vehicle_locations where shipment_id='c5000000-0000-0000-0000-000000000001';delete from public.documents where shipment_id='c5000000-0000-0000-0000-000000000001';delete from public.shipment_status_requests where shipment_id='c5000000-0000-0000-0000-000000000001';delete from public.shipments where id='c5000000-0000-0000-0000-000000000001';delete from public.vehicles where id='c4000000-0000-0000-0000-000000000001';delete from public.drivers where id='c2000000-0000-0000-0000-000000000001';delete from public.clients where id='c3000000-0000-0000-0000-000000000001';delete from public.profiles where id::text like 'c1000000-%';delete from auth.users where id::text like 'c1000000-%';drop function public.s3_reset(public.shipment_status,boolean,boolean);drop function public.s3_capture_cancel();drop function public.s3_capture_edit();drop function public.s3_capture_request();drop function public.s3_capture_approve();drop function public.s3_capture_reject();drop function public.s3_capture_account();drop function public.s3_capture_driver_lifecycle();drop function public.s3_capture_vehicle_lifecycle();drop function public.s3_capture_tracking_document_alert();$cleanup$);
select extensions.dblink_disconnect('s3_setup');
select * from finish();
rollback;
